INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'civilisation', 'n.', '/ˌsɪvəlaɪˈzeɪʃn/', '文明;文明社会', 'The Maya built one of the greatest civilisations in the Americas.', '玛雅人建立了美洲最伟大的文明之一。', 'The Mysteries of the Maya', 1, 0, 'senior', 'wordlist', 'elective4', 'U5', 'ancient civilisation', '美式拼 civilization;美音 /ˌsɪvələˈzeɪʃn/', 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'mystery', 'n.', '/ˈmɪstri/', '谜;神秘的事物', 'Why the Maya left their cities is still a mystery.', '玛雅人为何离开他们的城市仍是个谜。', 'The Mysteries of the Maya', 2, 0, 'senior', 'wordlist', 'elective4', 'U5', 'remain a mystery', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'intrigue', 'v.', '/ɪnˈtriːɡ/', '激起……的兴趣;引起……的好奇心', 'The lost city continued to intrigue young researchers everywhere.', '这座失落的城市持续激起各地年轻研究者的兴趣。', 'The Mysteries of the Maya', 3, 0, 'senior', 'wordlist', 'elective4', 'U5', 'intrigue scientists', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'bury', 'v.', '/ˈberi/', '埋;将……埋在下面', 'Thick jungle came to bury the old temples for hundreds of years.', '茂密的丛林把古老的神庙掩埋了数百年。', 'The Mysteries of the Maya', 4, 0, 'senior', 'wordlist', 'elective4', 'U5', 'bury deep in the jungle', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'pyramid', 'n.', '/ˈpɪrəmɪd/', '金字塔', 'The Maya built a huge stone pyramid in the centre of the city.', '玛雅人在城市中心建造了一座巨大的石头金字塔。', 'The Mysteries of the Maya', 5, 0, 'senior', 'wordlist', 'elective4', 'U5', 'step pyramid', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'astronomy', 'n.', '/əˈstrɒnəmi/', '天文学', 'Their knowledge of astronomy helped them make an accurate calendar.', '他们的天文学知识帮助他们制定了精确的历法。', 'The Mysteries of the Maya', 6, 0, 'senior', 'wordlist', 'elective4', 'U5', 'the study of astronomy', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'canal', 'n.', '/kəˈnæl/', '运河;水渠', 'The Maya dug a long canal to carry water to their fields.', '玛雅人挖了一条长长的水渠把水引到田里。', 'The Mysteries of the Maya', 7, 0, 'senior', 'wordlist', 'elective4', 'U5', 'dig a canal', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'tropical', 'adj.', '/ˈtrɒpɪkl/', '热带的;来自热带的', 'The cities were hidden deep inside a hot tropical forest.', '这些城市藏在炎热的热带森林深处。', 'The Mysteries of the Maya', 8, 0, 'senior', 'wordlist', 'elective4', 'U5', 'tropical forest', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'cyclone', 'n.', '/ˈsaɪkləʊn/', '气旋;旋风', 'Fewer than usual a cyclone reached the coast during those years.', '那些年到达海岸的气旋比往常更少。', 'The Mysteries of the Maya', 9, 0, 'senior', 'wordlist', 'elective4', 'U5', 'a tropical cyclone', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'downfall', 'n.', '/ˈdaʊnfɔːl/', '衰败;垮台', 'Droughts may have caused the downfall of the great cities.', '干旱也许导致了这些大城市的衰败。', 'The Mysteries of the Maya', 10, 0, 'senior', 'wordlist', 'elective4', 'U5', 'lead to the downfall', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'ruin', 'n.', '/ˈruːɪn/', '废墟;残垣断壁;毁灭', 'Today only a stone ruin marks where the city once stood.', '如今只有一片石头废墟标示着这座城市曾经的位置。', 'The Mysteries of the Maya', 11, 0, 'senior', 'wordlist', 'elective4', 'U5', 'fall into ruin', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'abandon', 'v.', '/əˈbændən/', '离弃;逃离;放弃', 'Something forced the people to abandon their homes forever.', '某种原因迫使人们永远离弃了自己的家园。', 'The Mysteries of the Maya', 12, 0, 'senior', 'wordlist', 'elective4', 'U5', 'abandon a city', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'dismiss', 'v.', '/dɪsˈmɪs/', '否定;不予考虑;驳回', 'Scholars were quick to dismiss the boy''s idea as a guess.', '学者们很快否定了这个男孩的想法,认为只是猜测。', 'The Mysteries of the Maya', 13, 0, 'senior', 'wordlist', 'elective4', 'U5', 'dismiss a theory', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'expansion', 'n.', '/ɪkˈspænʃn/', '扩大;增加;扩张', 'The expansion of the population called for more farmland.', '人口的增长需要更多的农田。', 'The Mysteries of the Maya', 14, 0, 'senior', 'wordlist', 'elective4', 'U5', 'rapid expansion', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'getaway', 'n.', '/ˈɡetəweɪ/', '逃跑;逃走', 'When danger appears, a quick getaway can be a sensible choice.', '危险出现时,迅速逃走可能是明智的选择。', 'The Mysteries of the Maya', 15, 0, 'senior', 'wordlist', 'elective4', 'U5', 'make a getaway', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'retreat', 'v.', '/rɪˈtriːt/', '后退;退避;离开', 'Some of our ancestors chose to retreat from the unknown.', '我们的一些祖先选择从未知中退避。', 'The Mysteries of the Maya', 16, 0, 'senior', 'wordlist', 'elective4', 'U5', 'retreat to safety', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'subdue', 'v.', '/səbˈdjuː/', '克制;抑制(情绪);制服', 'Brave explorers learn to subdue their fear and move ahead.', '勇敢的探险者学会克制恐惧、继续前进。', 'The Mysteries of the Maya', 17, 0, 'senior', 'wordlist', 'elective4', 'U5', 'subdue one''s fear', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'uncharted', 'adj.', '/ʌnˈtʃɑːtɪd/', '地图上没有标明的;未知的', 'Amundsen set out into uncharted land to reach the South Pole.', '阿蒙森动身进入地图上没有标明的土地,去往南极。', 'The Mysteries of the Maya', 18, 0, 'senior', 'wordlist', 'elective4', 'U5', 'uncharted territory', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'delve', 'v.', '/delv/', '探索;探究;钻研', 'These discoveries help us delve into the secrets of the deep sea.', '这些发现帮助我们探究深海的奥秘。', 'The Mysteries of the Maya', 19, 0, 'senior', 'wordlist', 'elective4', 'U5', 'delve into the past', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'shrink', 'v.', '/ʃrɪŋk/', '退缩;畏缩;(使)缩小', 'There is no need to shrink from a new and strange situation.', '没有必要在新奇而陌生的情境前退缩。', 'The Mysteries of the Maya', 20, 0, 'senior', 'wordlist', 'elective4', 'U5', 'shrink from a challenge', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'investigation', 'n.', '/ɪnˌvestɪˈɡeɪʃn/', '调查;研究', 'A careful investigation may finally solve this ancient puzzle.', '一项细致的调查也许最终能解开这个古老的谜题。', 'The Mysteries of the Maya', 21, 0, 'senior', 'wordlist', 'elective4', 'U5', 'carry out an investigation', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'shipwreck', 'n.', '/ˈʃɪprek/', '失事的船;沉船', 'Divers found an old shipwreck lying on the sea bed.', '潜水员发现一艘古老的沉船躺在海床上。', 'The Mysteries of the Maya', 22, 0, 'senior', 'wordlist', 'elective4', 'U5', 'an ancient shipwreck', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'archaeological', 'adj.', '/ˌɑːkiəˈlɒdʒɪkl/', '考古的;考古学的', 'Many archaeological finds are made in shallow waters near the coast.', '许多考古发现是在靠近海岸的浅水中取得的。', 'The Mysteries of the Maya', 23, 0, 'senior', 'wordlist', 'elective4', 'U5', 'an archaeological find', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'coral', 'n.', '/ˈkɒrəl/', '珊瑚', 'Some deep-sea coral may be four thousand years old.', '有些深海珊瑚可能有四千年之久。', 'The Mysteries of the Maya', 24, 0, 'senior', 'wordlist', 'elective4', 'U5', 'bone-white coral', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'millimetre', 'n.', '/ˈmɪliˌmiːtə/', '毫米', 'This coral grows only one or two millimetres each year.', '这种珊瑚每年只生长一到两毫米。', 'The Mysteries of the Maya', 25, 0, 'senior', 'wordlist', 'elective4', 'U5', 'a few millimetres a year', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'upwards', 'adv.', '/ˈʌpwədz/', '向上;朝上', 'The strange fish can look upwards through its clear forehead.', '这种奇怪的鱼能透过透明的额头向上看。', 'The Mysteries of the Maya', 26, 0, 'senior', 'wordlist', 'elective4', 'U5', 'look upwards', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'trench', 'n.', '/trentʃ/', '海沟;沟', 'In the deepest trench the pressure is almost unimaginable.', '在最深的海沟里,压力几乎难以想象。', 'The Mysteries of the Maya', 27, 0, 'senior', 'wordlist', 'elective4', 'U5', 'a deep ocean trench', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'equivalent', 'adj.', '/ɪˈkwɪvələnt/', '等同的;相当的;等值的', 'The pressure there is equivalent to fifty aeroplanes stacked up.', '那里的压力相当于五十架飞机叠在一起。', 'The Mysteries of the Maya', 28, 0, 'senior', 'wordlist', 'elective4', 'U5', 'equivalent to', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'stack', 'v.', '/stæk/', '(使)堆起;摞起', 'Imagine fifty planes stacked one on top of another.', '想象五十架飞机一架摞在另一架上面。', 'The Mysteries of the Maya', 29, 0, 'senior', 'wordlist', 'elective4', 'U5', 'stack one on top of another', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'furthermore', 'adv.', '/ˌfɜːðəˈmɔː/', '此外;而且;不仅如此', 'Furthermore, the oceans are a valuable source of natural resources.', '此外,海洋是宝贵的自然资源来源。', 'The Mysteries of the Maya', 30, 0, 'senior', 'wordlist', 'elective4', 'U5', 'furthermore, ...', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'notable', 'adj.', '/ˈnəʊtəbl/', '显著的;值得注意的;显要的', 'The most notable find was a strange ice-like substance.', '最值得注意的发现是一种奇怪的冰状物质。', 'The Mysteries of the Maya', 31, 0, 'senior', 'wordlist', 'elective4', 'U5', 'the most notable of these', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'substance', 'n.', '/ˈsʌbstəns/', '物质', 'China found an ice-like substance under the South China Sea.', '中国在南海下面发现了一种冰状物质。', 'The Mysteries of the Maya', 32, 0, 'senior', 'wordlist', 'elective4', 'U5', 'an ice-like substance', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'vessel', 'n.', '/ˈvesl/', '船;舰;容器', 'China''s underwater vessel reached a depth of seven thousand metres.', '中国的潜水器到达了七千米的深度。', 'The Mysteries of the Maya', 33, 0, 'senior', 'wordlist', 'elective4', 'U5', 'an underwater vessel', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'drilling', 'n.', '/ˈdrɪlɪŋ/', '钻探;勘探', 'The research helps identify good areas for deep-sea drilling.', '这项研究有助于确定适合深海钻探的区域。', 'The Mysteries of the Maya', 34, 0, 'senior', 'wordlist', 'elective4', 'U5', 'deep-sea drilling', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'volume', 'n.', '/ˈvɒljuːm/', '(书的)卷,册;音量;体积', 'She quoted a famous line from volume five of the old book.', '她引用了那本旧书第五卷里一句著名的话。', 'The Mysteries of the Maya', 35, 0, 'senior', 'wordlist', 'elective4', 'U5', 'volume five', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'fall into ruin', 'phr.', '/ˌfɔːl ɪntə ˈruːɪn/', '(因无人照料而)衰落,败落', 'Once-great cities can fall into ruin within a few generations.', '曾经辉煌的城市可能在几代人之内便衰落败落。', 'The Mysteries of the Maya', 36, 0, 'senior', 'wordlist', 'elective4', 'U5', 'fall into ruin', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'set out', 'phr.', '/ˌset ˈaʊt/', '动身;踏上(漫长的)旅途;着手', 'The explorers set out to find the city hidden in the jungle.', '探险者们出发去寻找藏在丛林中的城市。', 'The Mysteries of the Maya', 37, 0, 'senior', 'wordlist', 'elective4', 'U5', 'set out on a journey', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'the unknown', 'phr.', '/ðə ʌnˈnəʊn/', '不为人知的地方;未知事物', 'These reactions help humankind delve into the unknown.', '这些反应帮助人类探索未知。', 'The Mysteries of the Maya', 38, 0, 'senior', 'wordlist', 'elective4', 'U5', 'face the unknown', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'check out', 'phr.', '/ˌtʃek ˈaʊt/', '调查;查看;核实', 'You may be tempted to check out a strange object you find.', '你可能很想去查看一下发现的奇怪物体。', 'The Mysteries of the Maya', 39, 0, 'senior', 'wordlist', 'elective4', 'U5', 'check out a strange object', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'look into', 'phr.', '/ˈlʊk ɪntə/', '调查(问题);研究', 'We should always look into things first before we act.', '行动之前我们总该先把事情调查清楚。', 'The Mysteries of the Maya', 40, 0, 'senior', 'wordlist', 'elective4', 'U5', 'look into a problem', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'think twice', 'phr.', '/ˌθɪŋk ˈtwaɪs/', '再三考虑;慎重考虑', 'It is never wrong to think twice before taking action.', '行动之前慎重考虑从来都没有错。', 'The Mysteries of the Maya', 41, 0, 'senior', 'wordlist', 'elective4', 'U5', 'think twice before acting', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'steer clear of', 'phr.', '/ˌstɪə ˈklɪər əv/', '避开;从……处脱身', 'Sometimes it is safer to steer clear of the unfamiliar.', '有时避开陌生的事物会更安全。', 'The Mysteries of the Maya', 42, 0, 'senior', 'wordlist', 'elective4', 'U5', 'steer clear of danger', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'throw oneself into', 'phr.', '/ˌθrəʊ wʌnˈself ɪntə/', '积极投入到……中去', 'Exploration does not mean blindly to throw oneself into danger.', '探索并不意味着盲目地投身于危险之中。', 'The Mysteries of the Maya', 43, 0, 'senior', 'wordlist', 'elective4', 'U5', 'throw oneself into the unknown', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'test the waters', 'phr.', '/ˌtest ðə ˈwɔːtəz/', '试水;试探', 'He wanted to test the waters of a brand-new situation.', '他想试探一下全新情境的水深。', 'The Mysteries of the Maya', 44, 0, 'senior', 'wordlist', 'elective4', 'U5', 'test the waters', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'run for one''s life', 'phr.', '/ˌrʌn fə wʌnz ˈlaɪf/', '逃命', 'Our ancestors would run for their lives from wild animals.', '我们的祖先会为了逃命而躲开野兽。', 'The Mysteries of the Maya', 45, 0, 'senior', 'wordlist', 'elective4', 'U5', 'run for one''s life', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'make a getaway', 'phr.', '/ˌmeɪk ə ˈɡetəweɪ/', '逃跑;逃走', 'Making a quick getaway can be a natural and sensible response.', '迅速逃走可能是一种自然而明智的反应。', 'The Mysteries of the Maya', 46, 0, 'senior', 'wordlist', 'elective4', 'U5', 'make a quick getaway', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe4u5.01', '①主语从句与宾语从句(what / that / whether · if vs whether)', 'A2', 12, '外研社版选择性必修第四册 U5 — 从句缺主语或宾语时用 what;陈述完整事实用 that;表''是否''(尤其句首作主语、介词后、紧跟 or not)用 whether,此时不能用 if。', 1, 'elective4', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe4u5.02', '②表语从句与同位语从句(The question is whether… · the fact/idea/news THAT…)', 'A2', 12, '外研社版选择性必修第四册 U5 — 表语从句承接 be 动词,缺成分用 what、完整事实用 that、是否用 whether;同位语从句说明 fact/idea/news/belief 等名词的内容,内容完整用 that,内容为''是否''用 whether。', 2, 'elective4', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe4u5.03', '③名词性从句连接词的选择(that vs what · whether vs if · whatever/whoever/however)', 'A2', 12, '外研社版选择性必修第四册 U5 — 内容完整无缺用 that、缺成分用 what;''是否''用 whether(or not/介词后不用 if);表''无论……''引导让步或''凡是''用 whatever/whoever/however。', 3, 'elective4', 'U5', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.01'), '____ caused the Maya to abandon their cities is still unknown.', 'What', 'That', 'Which', 'Whether', 'A', '从句 caused 前缺主语,只有 what 能在句中作主语并引导主语从句。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.01'), 'The carvings prove ____ the Maya understood the stars very well.', 'what', 'that', 'which', 'whether', 'B', '从句内容完整、陈述事实,宾语从句用 that。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.01'), 'No one can read exactly ____ the old symbols mean.', 'that', 'whether', 'what', 'which', 'C', 'mean 后缺宾语,用 what 在从句中作宾语。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.01'), 'Experts are not sure ____ a drought alone destroyed the cities or not.', 'if', 'that', 'what', 'whether', 'D', '紧跟 or not 只能用 whether,不用 if。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.01'), '____ really puzzles archaeologists is the speed of the collapse.', 'What', 'That', 'Which', 'Whether', 'A', 'puzzles 前缺主语,主语从句用 what。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.01'), 'Many people believe ____ the Maya tracked the planets carefully.', 'what', 'that', 'which', 'whether', 'B', '内容完整的陈述,宾语从句用 that。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.01'), 'Their survival depended on ____ enough rain fell each year.', 'if', 'that', 'whether', 'what', 'C', '介词 on 后引导''是否''的从句用 whether,不用 if。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.01'), 'The guide explained ____ the ancient farmers grew in those wet fields.', 'that', 'whether', 'which', 'what', 'D', 'grew 后缺宾语,用 what 作宾语。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.01'), '____ the Maya had no metal tools makes their work all the more amazing.', 'That', 'What', 'Whether', 'Which', 'A', '从句内容完整、作主语陈述事实,用 That。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.01'), 'Scientists wonder ____ the survivors moved north or not.', 'if', 'whether', 'that', 'what', 'B', '紧跟 or not 用 whether,不用 if。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.01'), '____ the deep jungle still hides may never be fully known.', 'That', 'Which', 'What', 'Whether', 'C', 'hides 后缺宾语,主语从句用 What。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.01'), 'The ruins show clearly ____ a great people once lived there.', 'what', 'whether', 'which', 'that', 'D', '内容完整的陈述,宾语从句用 that。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.01'), 'Researchers cannot agree on ____ the ancient writing system recorded.', 'what', 'that', 'whether', 'which', 'A', 'recorded 后缺宾语,介词 on 后用 what 引导并作宾语。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.01'), 'We do not know ____ war or disease ended the cities or not.', 'if', 'whether', 'that', 'what', 'B', '紧跟 or not 用 whether。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.01'), 'The new study suggests ____ the droughts lasted for several years.', 'what', 'whether', 'that', 'which', 'C', '内容完整的陈述,宾语从句用 that。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.01'), '____ happened to the last Maya rulers remains a mystery.', 'That', 'Which', 'Whether', 'What', 'D', 'happened 前缺主语,主语从句用 What。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.01'), 'There is much debate about ____ the calendar was truly accurate.', 'whether', 'if', 'that', 'what', 'A', '介词 about 后引导''是否''的从句用 whether,不用 if。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.01'), 'Old records tell us ____ the city was once full of life.', 'what', 'that', 'whether', 'which', 'B', '内容完整的陈述,宾语从句用 that。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.01'), 'I often wonder ____ the ancient builders left behind in the jungle.', 'that', 'whether', 'what', 'which', 'C', 'left behind 后缺宾语,用 what 作宾语。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.01'), 'It is unclear ____ the warnings came too late or not.', 'if', 'that', 'what', 'whether', 'D', '紧跟 or not 用 whether。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.02'), 'The fact ____ the Maya had a true writing system surprises many people.', 'that', 'what', 'which', 'whether', 'A', '同位语从句说明 fact 的内容、内容完整,用 that。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.02'), 'The big question is ____ a single disaster destroyed them all or not.', 'if', 'whether', 'that', 'what', 'B', '表语从句、紧跟 or not,用 whether,不用 if。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.02'), 'The idea ____ farming changed the land seems very likely.', 'what', 'which', 'that', 'whether', 'C', '同位语从句说明 idea、内容完整,用 that。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.02'), 'That long silence is ____ still troubles every archaeologist.', 'that', 'which', 'whether', 'what', 'D', 'troubles 前缺主语,表语从句用 what。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.02'), 'The news ____ a new temple had been found excited the whole team.', 'that', 'what', 'whether', 'which', 'A', '同位语从句说明 news、内容完整,用 that。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.02'), 'The truth is ____ no one has fully read their writing yet.', 'what', 'that', 'whether', 'which', 'B', '表语从句、内容完整陈述事实,用 that。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.02'), 'The belief ____ the stars guided the Maya is a very old one.', 'what', 'which', 'that', 'whether', 'C', '同位语从句说明 belief、内容完整,用 that。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.02'), 'The real issue is ____ the rains failed for many years or not.', 'if', 'that', 'what', 'whether', 'D', '表语从句、紧跟 or not,用 whether。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.02'), 'There is strong evidence ____ the population grew far too fast.', 'that', 'what', 'whether', 'which', 'A', '同位语从句说明 evidence、内容完整,用 that。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.02'), 'This empty city is ____ remains of a once-great civilisation.', 'that', 'what', 'which', 'whether', 'B', 'remains 前缺主语,表语从句用 what(=所剩下的东西)。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.02'), 'The discovery ____ the calendar was accurate amazed the scientists.', 'what', 'which', 'that', 'whether', 'C', '同位语从句说明 discovery、内容完整,用 that。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.02'), 'Our main doubt is ____ the theory can ever be proved or not.', 'if', 'that', 'what', 'whether', 'D', '表语从句、紧跟 or not,用 whether。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.02'), 'The hope ____ the writing will one day be read keeps them going.', 'that', 'what', 'whether', 'which', 'A', '同位语从句说明 hope、内容完整,用 that。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.02'), 'A true writing system was ____ made the Maya unique in the Americas.', 'that', 'what', 'which', 'whether', 'B', 'made 前缺主语,表语从句用 what。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.02'), 'The theory ____ humans harmed the land has gained much support.', 'what', 'which', 'that', 'whether', 'C', '同位语从句说明 theory、内容完整,用 that。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.02'), 'One surprising fact is ____ the cities were never rebuilt.', 'what', 'whether', 'which', 'that', 'D', '表语从句、内容完整陈述事实,用 that。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.02'), 'The question ____ the people left by choice still divides experts.', 'whether', 'that', 'what', 'if', 'A', '同位语从句说明 question 的''是否''内容,用 whether;question 后不用 if 引导同位语。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.02'), 'The mystery is ____ the drought alone caused everything or not.', 'if', 'whether', 'that', 'what', 'B', '表语从句、紧跟 or not,用 whether。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.02'), 'The fact ____ they built without the wheel makes it more amazing.', 'what', 'which', 'that', 'whether', 'C', '同位语从句说明 fact、内容完整,用 that。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.02'), 'The Maya calendar is ____ first drew me to study this people.', 'that', 'which', 'whether', 'what', 'D', 'drew 前缺主语,表语从句用 what。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.03'), 'Everyone agrees ____ the Maya were remarkably skilled builders.', 'that', 'what', 'which', 'whether', 'A', '内容完整的陈述,用 that;无缺成分不用 what。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.03'), 'Nobody knows for sure ____ lies beneath the jungle floor.', 'that', 'what', 'which', 'whether', 'B', 'lies 前缺主语,用 what;内容有缺不用 that。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.03'), 'Tell me ____ the city was abandoned suddenly or not.', 'if', 'that', 'whether', 'what', 'C', '紧跟 or not 用 whether,不用 if。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.03'), '____ the ancient farmers harvested each year fed a huge population.', 'That', 'Which', 'Whether', 'What', 'D', 'harvested 后缺宾语,主语从句用 What;内容有缺不用 That。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.03'), 'The old map shows ____ the cities lay close to certain bright stars.', 'that', 'what', 'whether', 'which', 'A', '内容完整的陈述,用 that。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.03'), 'Much still depends on ____ the rains will return this season.', 'if', 'whether', 'that', 'what', 'B', '介词 on 后引导''是否''的从句用 whether,不用 if。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.03'), 'The Maya carefully recorded ____ they saw in the night sky.', 'whoever', 'however', 'whatever', 'whichever', 'C', '作 recorded 与 saw 的宾语、指''凡是看到的事物'',用 whatever。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.03'), '____ first entered the silent ruins must have felt truly amazed.', 'Whatever', 'However', 'Whichever', 'Whoever', 'D', '指''无论是谁''、作主语并指人,用 Whoever。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.03'), '____ hard scientists search, some answers still stay hidden.', 'However', 'Whatever', 'Whoever', 'Whichever', 'A', '后接形容词 hard 表''无论多么……'',用 However。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.03'), 'It is now clear ____ a great people once lived in these valleys.', 'what', 'that', 'whether', 'which', 'B', '内容完整的陈述,用 that。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.03'), 'The priests'' writing recorded ____ the rulers wanted to remember.', 'that', 'whether', 'what', 'which', 'C', 'remember 后缺宾语,用 what。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.03'), 'Ask the local guide ____ the temple is open to visitors or not.', 'if', 'that', 'what', 'whether', 'D', '紧跟 or not 用 whether。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.03'), 'The jungle slowly covered ____ the people had left behind.', 'whatever', 'whoever', 'however', 'whichever', 'A', '作 covered 与 left 的宾语、指''凡是留下的东西'',用 whatever。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.03'), 'A rich reward would go to ____ first found the lost city.', 'whatever', 'whoever', 'however', 'whichever', 'B', '指''无论是谁''、指人作 found 的主语,用 whoever。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.03'), '____ carefully we look, the true cause is hard to find.', 'Whatever', 'Whoever', 'However', 'Whichever', 'C', '后接副词 carefully 表''无论多么……'',用 However。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.03'), 'Few people doubt ____ the calendar was a great achievement.', 'what', 'whether', 'which', 'that', 'D', '否定句 few...doubt 后内容完整,用 that。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.03'), '____ destroyed the great cities is still fiercely debated today.', 'What', 'That', 'Which', 'Whether', 'A', 'destroyed 前缺主语,主语从句用 What。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.03'), 'There is real doubt about ____ war played any part at all.', 'if', 'whether', 'that', 'what', 'B', '介词 about 后引导''是否''的从句用 whether,不用 if。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.03'), 'Future explorers will study ____ the deep jungle finally reveals.', 'whoever', 'however', 'whatever', 'whichever', 'C', '作 study 与 reveals 的宾语、指''凡是揭示出的东西'',用 whatever。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U5' AND code='fe4u5.03'), 'Old legends say ____ the gods once walked among the people.', 'what', 'whether', 'which', 'that', 'D', '内容完整的陈述,用 that。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Mysteries of the Maya', 'China is not the only land with an ancient past full of wonder. Far across the ocean, in the hot forests of Central America, the Maya created one of the greatest civilisations the world has ever seen. They raised tall stone pyramids, traced the movements of the stars, and produced a calendar so exact that it lost only a few seconds each year. Most amazing of all, they did this without the wheel, without metal tools, and without any large animals to help them carry heavy loads. The Maya also invented a true writing system of more than eight hundred signs, some standing for objects and some for sounds. Even today, no one has been able to read every part of it. By around 700 AD their cities were at their peak, yet within a few generations these cities were left empty and slowly swallowed by the jungle. Why such a clever people gave up their homes is a puzzle that still draws curious minds from around the world.', '说明·玛雅文明概述', 169, '[{"q":"What made the Maya''s achievements especially remarkable?","answer":"A","options":["They managed all this without wheels, metal tools or large animals.","They had modern machines to help them work.","They simply copied a nearby civilisation.","They were guided by European explorers."],"explanation":"原文指出他们没有轮子、金属工具和大型牲畜却完成这些,选项为其转述。"},{"q":"What does the text say about the Maya writing system?","answer":"B","options":["It has been completely understood.","Part of it still cannot be read today.","It used only ten simple signs.","It was borrowed from the Chinese."],"explanation":"原文 ''no one has been able to read every part of it'' 的转述。"},{"q":"What happened to the Maya cities after about 700 AD?","answer":"A","options":["They were left empty and taken over by the forest.","They kept growing larger every year.","They were all rebuilt in stronger stone.","They were moved closer to the coast."],"explanation":"原文 ''left empty and slowly swallowed by the jungle'' 的转述。"}]'::jsonb, '[{"word":"civilisation","cn":"文明"},{"word":"pyramid","cn":"金字塔"},{"word":"astronomy(stars)","cn":"天文(星象)"}]'::jsonb, 2, 'elective4', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'A Teenager''s Star Map', 'In 2016, a fifteen-year-old Canadian boy named William Gadoury made headlines around the world. He had been fascinated by the Maya since he was very young, and he spent hours studying ancient star charts. Comparing them with maps, he noticed something strange: the positions of the known Maya cities seemed to match the patterns of the stars. If the old cities lined up with the stars, he reasoned, then there might be another city, still unknown, hidden deep in the jungle where one bright star pointed. He even gave his imagined city a name. Newspapers loved the story of the clever teenager who might have found a city from his own bedroom. Scholars, however, were not convinced. They dismissed his theory, saying the shapes he saw were probably just chance. Yet whatever the truth may be, William''s idea showed how strongly the mysteries of the Maya still pull at the human imagination, inviting both children and experts alike to dream.', '记叙·少年甘德瑞的星图', 160, '[{"q":"Why did William Gadoury become famous?","answer":"B","options":["He personally dug up a buried Maya city.","He suggested a hidden Maya city might exist by studying the stars.","He was the first person to read Maya writing.","He built a large model of a Maya pyramid."],"explanation":"原文讲他通过对比星图推测丛林中可能有未知城市,选项为转述。"},{"q":"How did scholars react to his theory?","answer":"C","options":["They fully agreed with every part of it.","They paid him to keep working on it.","They rejected it as most likely only coincidence.","They asked him to lead an expedition."],"explanation":"原文 ''dismissed his theory, saying the shapes... were probably just chance'' 的转述。"},{"q":"What does the writer think William''s story shows?","answer":"D","options":["The Maya civilisation never really existed.","Ancient star charts are useless today.","Only trained experts care about the Maya.","The Maya mysteries still capture people''s imagination."],"explanation":"末句 ''still pull at the human imagination'' 的转述。"}]'::jsonb, '[{"word":"intrigue(fascinated)","cn":"激起兴趣"},{"word":"dismiss","cn":"否定"},{"word":"the unknown","cn":"未知"}]'::jsonb, 2, 'elective4', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Why the Cities Were Abandoned', 'Why did the Maya leave their great cities? After many years of study, scientists still cannot give one simple answer. Several causes probably worked together. As the population grew, the people needed more and more land. They turned wetlands into fields and cut down forests for wood, changing the landscape around them. In doing so, they may have weakened the land''s natural ability to deal with hard times. Then the weather turned against them. Studies suggest that, between 700 and 1000 AD, far fewer storms than usual reached the region, leading to a long series of droughts. With less rain, crops failed, food ran short, and quarrels between cities grew worse. Many researchers now believe these droughts were the main reason the cities began to fall, though they collapsed at different speeds in different places. Whatever the exact mix of causes, the once-busy cities were finally abandoned, falling into ruin and leaving behind only silent stone for later people to wonder at.', '说明·城市衰亡的原因', 162, '[{"q":"Why is the Maya collapse hard to explain?","answer":"A","options":["Several causes most likely acted together.","There was clearly just one single cause.","No records of the period survive at all.","The cities never actually fell at all."],"explanation":"原文 ''Several causes probably worked together'' 的转述。"},{"q":"How might the people themselves have harmed their land?","answer":"B","options":["By moving all their cities to the coast.","By clearing forests and draining wetlands for farming.","By refusing to grow any crops at all.","By building far too few houses."],"explanation":"原文 ''turned wetlands into fields and cut down forests'' 的转述。"},{"q":"What do many researchers see as the main cause of the collapse?","answer":"C","options":["A single sudden flood.","An invasion from across the sea.","A long period of repeated droughts.","A loss of their writing system."],"explanation":"原文 ''these droughts were the main reason'' 的转述。"}]'::jsonb, '[{"word":"expansion(grew)","cn":"扩张"},{"word":"abandon","cn":"离弃"},{"word":"fall into ruin","cn":"衰落败落"}]'::jsonb, 2, 'elective4', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Secrets of the Deep Ocean', 'The sea hides as many secrets as the jungle. Beneath the waves lie an estimated three million shipwrecks, each one a story of people reaching for the edges of their world. Sometimes whole towns rest under the water. Off the coast of Tunisia, divers found the ancient Roman city of Neapolis, thought to have been swallowed by a giant wave around the fourth century. Its quiet streets and buildings are almost two thousand years old, offering a window onto a distant age. The deep ocean is also home to creatures stranger than any story. Far below the reach of sunlight grow corals that add only a millimetre or two each year, so that some of them may be four thousand years old. Strange fish drift through the blackness, and in the deepest trenches the pressure is crushing. Yet life still clings on, even there. Each new dive reminds us how little of our own planet we have so far truly explored.', '说明·深海中的古城与生命', 161, '[{"q":"What does the writer compare the sea to at the start?","answer":"D","options":["A desert, because both are empty.","A city, because both are crowded.","The sky, because both are bright.","The jungle, because both hide many secrets."],"explanation":"原文首句把海洋与丛林并列,都藏着秘密,为其转述。"},{"q":"What is special about the city of Neapolis?","answer":"A","options":["A whole ancient town lies preserved under the sea.","It is a busy modern port today.","It was built only a few years ago.","It stands high up in the mountains."],"explanation":"原文讲整座古罗马城沉在海下、街道建筑近两千年,为其转述。"},{"q":"What does the writer say about deep-sea corals?","answer":"B","options":["They die within a single year.","They grow extremely slowly and can be very old.","They grow faster than any land plant.","They cannot live unless sunlight reaches them."],"explanation":"原文 ''add only a millimetre or two each year... four thousand years old'' 的转述。"}]'::jsonb, '[{"word":"shipwreck","cn":"沉船"},{"word":"coral","cn":"珊瑚"},{"word":"trench","cn":"海沟"}]'::jsonb, 2, 'elective4', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Facing the Unknown', 'When something strange suddenly appears, many of us feel a sharp urge to run. This ''flight instinct'' is very old. Long ago, making a quick getaway often kept our ancestors alive, helping them escape wild animals, fire and other dangers. So when you meet a strange object or a new situation, part of you may want to steer clear of it, and that caution can sometimes be wise. Yet not everyone follows this instinct. Instead of retreating to safety, some of our ancestors chose to subdue their fear and step towards the unknown. That same curiosity led people to discover the use of fire and, much later, to set out across uncharted seas and ice. The explorer Roald Amundsen, for example, crossed one of the harshest places on Earth to reach the South Pole. Such bravery has pushed humankind forward. Of course, wise explorers still think twice and look into things first; courage does not mean throwing yourself blindly into danger.', '议论·面对未知的两种反应', 161, '[{"q":"Why does the writer say the flight instinct developed?","answer":"C","options":["People in the past simply disliked any exercise.","It made hunting large animals much easier.","Running away once helped early people survive real dangers.","It helped ancient people sleep better at night."],"explanation":"原文 ''keeping our ancestors alive, helping them escape... dangers'' 的转述。"},{"q":"What did some ancestors do instead of running away?","answer":"D","options":["They hid inside caves for the rest of their lives.","They quickly forgot how to use fire.","They gave up all sense of curiosity.","They controlled their fear and explored the unknown."],"explanation":"原文 ''subdue their fear and step towards the unknown'' 的转述。"},{"q":"What does the writer say about wise exploration?","answer":"A","options":["It still involves careful thought, not blind risk.","It means rushing into every possible danger.","It should always be completely avoided.","It is only ever suitable for famous people."],"explanation":"原文 ''think twice and look into things first... not throwing yourself blindly'' 的转述。"}]'::jsonb, '[{"word":"getaway","cn":"逃走"},{"word":"subdue","cn":"克制"},{"word":"uncharted","cn":"未标明的"}]'::jsonb, 2, 'elective4', 'U5', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'China Explores the Deep Sea', 'Today many countries are racing to explore the deep ocean, and China has become one of the leaders. Its underwater vessels, such as the Jiaolong and the Shenhai Yongshi, can dive thousands of metres below the surface. The Jiaolong once reached a depth of over seven thousand metres, setting a record for a crewed dive and placing China among the world''s top ocean explorers. These vessels do far more than break records. The research they carry out helps scientists understand how the sea bed was formed and where useful resources might lie. One of the most notable finds is a strange ice-like substance, often called ''fire ice'', discovered under the South China Sea. It may one day become an important source of energy. Furthermore, the data gathered helps identify good areas for deep-sea drilling. Step by step, such work is opening a new age of discovery, in which the world beneath the waves may grow as familiar to us as the land above.', '说明·中国的深海探索', 163, '[{"q":"What record did the Jiaolong set?","answer":"B","options":["The fastest ship on the ocean surface.","The deepest dive ever made by a crewed submarine.","The longest bridge ever built over water.","The largest fishing boat in all of Asia."],"explanation":"原文 ''a record for a crewed dive... over seven thousand metres'' 的转述。"},{"q":"Why is ''fire ice'' described as important?","answer":"C","options":["It is mainly used to keep drinks cold.","It is a rare kind of deep-sea fish.","It could one day serve as a valuable source of energy.","It helps make the ocean water warmer."],"explanation":"原文 ''may one day become an important source of energy'' 的转述。"},{"q":"Besides setting records, what do the vessels help scientists do?","answer":"D","options":["Catch many more fish for food.","Travel faster than modern aeroplanes.","Take the place of satellites in space.","Learn how the sea bed formed and where resources lie."],"explanation":"原文 ''understand how the sea bed was formed and where useful resources might lie'' 的转述。"}]'::jsonb, '[{"word":"vessel","cn":"船;潜水器"},{"word":"substance","cn":"物质"},{"word":"drilling","cn":"钻探"}]'::jsonb, 2, 'elective4', 'U5', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U5', 'A Visit to a Maya Pyramid', 'Last summer my family travelled to Central America to (1)____ the ruins of an old Maya city. As we walked into the jungle, a huge stone (2)____ suddenly rose up in front of us, taller than any building I had ever seen. Our guide told us that the Maya had (3)____ it hundreds of years ago without any metal tools. I found that very hard to (4)____. From the top, we could see green forest stretching in every (5)____. The guide explained that the Maya were great watchers of the (6)____, and that their calendar was extremely (7)____. Walking among the silent stones, I began to (8)____ why so many people are drawn to this place. It felt as if the city still kept many (9)____ that no one had solved. That trip made me want to (10)____ more about ancient civilisations.', 142, 2, '[{"q":"1","answer":"A","options":["visit","sell","throw","cook"],"explanation":"visit the ruins 参观遗址。"},{"q":"2","answer":"B","options":["river","pyramid","song","market"],"explanation":"a stone pyramid 石头金字塔。"},{"q":"3","answer":"C","options":["sold","lost","built","bought"],"explanation":"had built it 建造了它。"},{"q":"4","answer":"D","options":["forget","sell","lose","believe"],"explanation":"hard to believe 难以置信。"},{"q":"5","answer":"A","options":["direction","colour","price","sound"],"explanation":"in every direction 朝各个方向。"},{"q":"6","answer":"B","options":["shops","stars","prices","games"],"explanation":"watchers of the stars 观星者。"},{"q":"7","answer":"C","options":["cheap","loud","accurate","empty"],"explanation":"extremely accurate 极其精确。"},{"q":"8","answer":"D","options":["forget","sell","lose","understand"],"explanation":"began to understand 开始明白。"},{"q":"9","answer":"A","options":["mysteries","prices","songs","tickets"],"explanation":"many mysteries 许多谜团。"},{"q":"10","answer":"B","options":["forget","learn","sell","hide"],"explanation":"learn more about 了解更多。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U5', 'The Lost City in the Jungle', 'For many years, the explorer Maria had dreamed of finding a lost Maya city. With a small team, she finally (1)____ out into the thick jungle. The heat was terrible, and the (2)____ forest made it hard to see more than a few metres ahead. Many people had told her the city was only a (3)____, but she refused to give up. On the fifth day, her guide pointed at a strange (4)____ hill covered in trees. When they cleared away the plants, they found the (5)____ of an ancient wall. Maria could hardly (6)____ her eyes. Slowly, the shape of an old (7)____ appeared beneath the green. She felt sure that this discovery would (8)____ the interest of scientists everywhere. That night she wrote in her (9)____ that the jungle still hid more secrets than anyone could (10)____.', 139, 2, '[{"q":"1","answer":"C","options":["sold","lost","set","ate"],"explanation":"set out 动身出发。"},{"q":"2","answer":"D","options":["empty","cheap","loud","tropical"],"explanation":"tropical forest 热带森林。"},{"q":"3","answer":"A","options":["story","price","song","ticket"],"explanation":"only a story 只是个传说。"},{"q":"4","answer":"B","options":["cheap","low","loud","sweet"],"explanation":"a low hill 低矮的小丘。"},{"q":"5","answer":"C","options":["prices","songs","ruins","games"],"explanation":"the ruins of a wall 一段墙的废墟。"},{"q":"6","answer":"D","options":["sell","forget","lose","believe"],"explanation":"hardly believe her eyes 不敢相信自己的眼睛。"},{"q":"7","answer":"A","options":["pyramid","market","garden","shop"],"explanation":"an old pyramid 一座古老的金字塔。"},{"q":"8","answer":"B","options":["lose","draw","break","sell"],"explanation":"draw the interest 吸引兴趣。"},{"q":"9","answer":"C","options":["price","song","diary","ticket"],"explanation":"wrote in her diary 写在日记里。"},{"q":"10","answer":"D","options":["sell","lose","forget","imagine"],"explanation":"more than anyone could imagine 超乎想象。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U5', 'Reading the Maya Calendar', 'The Maya are famous for their amazing (1)____, which could measure the year with great accuracy. To build it, they spent many nights (2)____ the movements of the stars and planets. They also created a (3)____ system of more than eight hundred signs. Some signs stood for whole words, while (4)____ stood for sounds. For a long time, no one could (5)____ what these signs meant, and the writing remained a complete (6)____. Slowly, modern scholars have (7)____ many of the signs, though some parts are still not clear. Each new discovery helps us (8)____ how clever this ancient people really were. It is (9)____ that they reached such knowledge without any modern machines. Studying the Maya makes me (10)____ how much skill lies hidden in the past.', 128, 2, '[{"q":"1","answer":"A","options":["calendar","market","garden","price"],"explanation":"amazing calendar 惊人的历法。"},{"q":"2","answer":"B","options":["selling","watching","eating","buying"],"explanation":"watching the movements of the stars 观察星象。"},{"q":"3","answer":"C","options":["cooking","shopping","writing","farming"],"explanation":"a writing system 书写系统。"},{"q":"4","answer":"D","options":["prices","songs","games","others"],"explanation":"while others 而另一些。"},{"q":"5","answer":"A","options":["understand","sell","throw","lose"],"explanation":"understand what they meant 看懂含义。"},{"q":"6","answer":"B","options":["price","mystery","song","game"],"explanation":"a complete mystery 完全的谜。"},{"q":"7","answer":"C","options":["sold","lost","read","thrown"],"explanation":"have read many signs 已读懂许多符号。"},{"q":"8","answer":"D","options":["sell","lose","forget","see"],"explanation":"helps us see 帮助我们看清。"},{"q":"9","answer":"A","options":["amazing","cheap","loud","empty"],"explanation":"It is amazing that 令人惊叹。"},{"q":"10","answer":"B","options":["sell","realise","lose","forget"],"explanation":"makes me realise 让我意识到。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U5', 'A Diver''s First Deep Dive', 'Tom had trained for months for his first (1)____ into the deep sea. Sitting inside the small underwater (2)____, he watched the sunlight slowly disappear as he sank. Soon everything around him was completely (3)____. His heart was beating fast, but he tried to (4)____ his fear and stay calm. Through the window he saw strange (5)____ that glowed in the darkness, creatures he had only seen in books. The (6)____ outside was so great that it could crush an ordinary boat. Tom carefully recorded (7)____ he saw, knowing the data would be useful to scientists. He realised how (8)____ of the ocean people had really explored. When at last he rose back towards the (9)____, he felt proud and amazed. That dive made him want to (10)____ into the secrets of the deep for the rest of his life.', 140, 2, '[{"q":"1","answer":"C","options":["song","price","dive","game"],"explanation":"his first dive 第一次下潜。"},{"q":"2","answer":"D","options":["garden","market","shop","vessel"],"explanation":"underwater vessel 潜水器。"},{"q":"3","answer":"A","options":["dark","cheap","loud","sweet"],"explanation":"completely dark 一片漆黑。"},{"q":"4","answer":"B","options":["sell","subdue","lose","buy"],"explanation":"subdue his fear 克制恐惧。"},{"q":"5","answer":"C","options":["prices","songs","fish","games"],"explanation":"strange fish 奇怪的鱼。"},{"q":"6","answer":"D","options":["price","song","noise","pressure"],"explanation":"the pressure outside 外面的压力。"},{"q":"7","answer":"A","options":["whatever","whoever","however","whichever"],"explanation":"recorded whatever he saw 记录所见的一切(指物作宾语)。"},{"q":"8","answer":"B","options":["cheap","little","loud","sweet"],"explanation":"how little of the ocean 海洋被探索得多么少。"},{"q":"9","answer":"C","options":["garden","market","surface","shop"],"explanation":"towards the surface 朝水面。"},{"q":"10","answer":"D","options":["sell","lose","buy","delve"],"explanation":"delve into the secrets 探究奥秘。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U5', 'An Explorer at the South Pole', 'More than a hundred years ago, the explorer Roald Amundsen set out to reach the South (1)____. The land ahead was completely (2)____, with no maps to guide him. Day after day, his team faced freezing winds and endless (3)____. Many people back home thought the journey was too (4)____ and warned him to turn back. But Amundsen refused to (5)____ from the challenge. He had planned every detail with great (6)____, and he trusted his team completely. At last, after weeks of hardship, they (7)____ the Pole and made history. Amundsen later wrote that real courage does not mean rushing blindly into (8)____. A wise explorer, he said, must always (9)____ twice and study the dangers first. His story still (10)____ young people to follow their dreams.', 128, 2, '[{"q":"1","answer":"A","options":["Pole","price","song","game"],"explanation":"the South Pole 南极。"},{"q":"2","answer":"B","options":["cheap","uncharted","loud","sweet"],"explanation":"completely uncharted 完全未标明的。"},{"q":"3","answer":"C","options":["songs","prices","snow","games"],"explanation":"endless snow 无尽的冰雪。"},{"q":"4","answer":"D","options":["cheap","loud","sweet","dangerous"],"explanation":"too dangerous 太危险。"},{"q":"5","answer":"A","options":["shrink","sell","buy","lose"],"explanation":"shrink from the challenge 在挑战前退缩。"},{"q":"6","answer":"B","options":["price","care","song","noise"],"explanation":"with great care 非常用心。"},{"q":"7","answer":"C","options":["sold","lost","reached","ate"],"explanation":"reached the Pole 到达极点。"},{"q":"8","answer":"D","options":["price","song","game","danger"],"explanation":"rushing into danger 冲入危险。"},{"q":"9","answer":"A","options":["think","sell","lose","buy"],"explanation":"think twice 三思而行。"},{"q":"10","answer":"B","options":["sells","inspires","loses","breaks"],"explanation":"inspires young people 激励年轻人。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U5', 'Life in the Dark Ocean', 'The deepest parts of the ocean are among the strangest places on (1)____. No sunlight ever reaches them, so they are always (2)____. Yet, surprisingly, they are full of (3)____. Some fish there make their own light to find food in the blackness. Beautiful (4)____ grow slowly on the sea bed, adding only a millimetre or two each (5)____, so a single one may be thousands of years old. In the deepest (6)____, the water presses down with enormous force. For a long time, these places were beyond the (7)____ of human beings. Today, modern vessels allow scientists to (8)____ into this hidden world. Each dive helps us (9)____ how life can survive in such hard conditions. (10)____, the deep ocean may still hold many resources that we have not yet found.', 132, 2, '[{"q":"1","answer":"C","options":["price","song","Earth","game"],"explanation":"places on Earth 地球上的地方。"},{"q":"2","answer":"D","options":["cheap","loud","sweet","dark"],"explanation":"always dark 永远黑暗。"},{"q":"3","answer":"A","options":["life","prices","songs","games"],"explanation":"full of life 充满生命。"},{"q":"4","answer":"B","options":["prices","corals","songs","games"],"explanation":"beautiful corals 美丽的珊瑚。"},{"q":"5","answer":"C","options":["price","song","year","game"],"explanation":"each year 每年。"},{"q":"6","answer":"D","options":["markets","gardens","shops","trenches"],"explanation":"the deepest trenches 最深的海沟。"},{"q":"7","answer":"A","options":["reach","price","song","game"],"explanation":"beyond the reach of 超出……的能力范围。"},{"q":"8","answer":"B","options":["sell","look","lose","buy"],"explanation":"look into this world 探究这个世界。"},{"q":"9","answer":"C","options":["sell","lose","understand","buy"],"explanation":"helps us understand 帮助我们理解。"},{"q":"10","answer":"D","options":["Sadly","Never","Quietly","Furthermore"],"explanation":"Furthermore 此外(补充新信息)。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U5 听力·对话 Planning a Trip to the Maya Ruins', '外研社版选择性必修第四册 U5 · dialogue', 3, 'Lily: Sam, our class is planning a trip to the Maya ruins next month. Are you coming?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U5 听力·短文 The Maya Calendar', '外研社版选择性必修第四册 U5 · passage', 2, 'The Maya were remarkable watchers of the sky.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U5 听力·对话 Why Did the Cities Fall?', '外研社版选择性必修第四册 U5 · dialogue', 3, 'Emma: Jack, our history question asks why the Maya cities were abandoned. Any ideas?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U5 听力·短文 How Little We Know the Sea', '外研社版选择性必修第四册 U5 · passage', 2, 'Beneath the oceans lie about three million shipwrecks.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U5 听力·对话 Talking to an Explorer', '外研社版选择性必修第四册 U5 · dialogue', 3, 'Host: Dr Reed, you''ve explored some of the wildest places on Earth. What drives you?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U5 听力·短文 A Word on Curiosity', '外研社版选择性必修第四册 U5 · passage', 2, 'Throughout history, curiosity has pushed humankind forward.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (12, 'Write an Article about an Unexplained Mystery(写一篇关于未解之谜的文章)', 'The Mystery of the Maya Collapse', '请用英语写一篇约120词的短文,介绍一个让你着迷的历史未解之谜(如玛雅文明的消失)。内容包括:① 用一个名词性从句点出谜题;② 列出一两种可能的解释;③ 表达哪些已知、哪些仍不确定;④ 给出你的思考或结论。注意尽量自然地使用主语/宾语/表语/同位语从句。', 'Write an article of about 120 words about a historical mystery that fascinates you (for example, the disappearance of the Maya). Include: 1) a noun clause that introduces the mystery; 2) one or two possible explanations; 3) what is known and what is still uncertain; 4) your own reflection or conclusion. Try to use subject, object, predicative and appositive clauses naturally.', '["用主语/同位语从句引出谜题(One mystery is what… / The fact that…)","列出可能的原因(Some believe that… others argue that…)","用 whether / what 从句表达不确定与已知(Whether… remains unclear; What we know is that…)","给出思考或结论(Why… may never be answered, but…)"]'::jsonb, 70, 100, 'One of the greatest mysteries in history is what caused the Maya to abandon their cities. The fact that such a clever people simply disappeared still puzzles scientists today. Some believe that years of drought destroyed their crops, while others argue that the people themselves harmed the land. Whether a single disaster or many causes ended the civilisation remains unclear. What we do know is that, within a few generations, the great cities fell into ruin. Perhaps the most important lesson is that no civilisation, however great, can ignore the world around it. Why the Maya vanished may never be fully answered, but the search for the truth still draws curious minds from all over the world.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["One of the greatest mysteries in history is what caused the Maya to abandon their cities.","The fact that such a clever people simply disappeared still puzzles scientists today.","Whether a single disaster or many causes ended the civilisation remains unclear.","What we do know is that the great cities fell into ruin within a few generations."]'::jsonb, '[{"wrong":"The fact what they disappeared puzzles us.","correct":"The fact that they disappeared puzzles us.","note":"同位语从句内容完整,用 that 引导,不用 what。"},{"wrong":"It is unclear if a drought caused it or not.","correct":"It is unclear whether a drought caused it or not.","note":"紧跟 or not 只能用 whether,不用 if。"},{"wrong":"What caused the collapse are still debated.","correct":"What caused the collapse is still debated.","note":"主语从句作主语时,谓语动词用单数 is。"}]'::jsonb, '【未解之谜文章结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (12, 'elective4', 'U5', '{"title":"名词性从句(主语/宾语/表语/同位语)速查","intro":"名词性从句在句中相当于一个名词,可作主语、宾语、表语或同位语。判断连接词的口诀:从句缺成分→用 what;内容完整陈述事实→用 that;表''是否''→用 whether(or not/介词后不用 if);表''无论……''→用 whatever/whoever/however。","table":{"headers":["从句类型","位置 / 常用连接词 / 例句"],"rows":[["主语从句","句首作主语:What caused the collapse is unknown. / That they had no metal tools is amazing."],["宾语从句","动词或介词后:No one knows what the signs mean. / It depends on whether the rains return."],["表语从句","be 动词后:The question is whether the drought lasted. / The truth is that no one has read it all."],["同位语从句","说明 fact/idea/news/belief 等名词:The fact that they vanished still puzzles us."]]},"specialRules":[{"rule":"从句缺主语/宾语→what;内容完整→that","mark":"what they planted(缺宾语) / that they planted crops(完整)"},{"rule":"表''是否'':句首作主语、介词后、紧跟 or not 时只能用 whether,不用 if","mark":"whether… or not √ / if… or not ×"},{"rule":"同位语从句内容完整用 that;但 question/doubt 后表''是否''用 whether","mark":"the fact that… / the question whether…"},{"rule":"表''无论……'':whatever(物)/ whoever(人)/ however+形容词或副词","mark":"recorded whatever they saw / however hard they looked"},{"rule":"主语从句作主语,谓语动词用单数","mark":"What caused it is(单数) still debated."}],"why":["what 自身在从句里充当主语或宾语,所以从句会''缺一块'';that 只起连接作用、不充当成分,所以从句必须完整。先看从句缺不缺成分,就能在 that 与 what 之间快速分辨。"],"gaokaoPoints":["that vs what(看从句是否缺主语/宾语);whether vs if(or not、介词后、句首主语只用 whether);语法填空与改错高频。","同位语从句 the fact/idea/news that… 与定语从句的区别:同位语从句内容完整、that 不作成分,定语从句中关系词要作成分。"],"examVsReal":[{"exam":"I don''t know whether he will come or not.（考试/书面)","real":"I don''t know if he''ll come.","note":"口语中宾语从句 if/whether 常通用;但 or not、介词后、句首主语只能 whether"},{"exam":"What he said is true.（考试强调主语从句)","real":"It''s true, what he said.","note":"口语常先说结论再补从句,书面则把主语从句放句首"}]}'::jsonb, 'fltrp');
